        fill={fill}
      />
      <path
        d="M34.9577 5.90647C34.2444 5.24759 33.2711 4.9192 32.0379 4.9192C30.4539 4.9192 29.2578 5.49824 28.4466 6.6579L29.9167 7.58171C30.4603 6.79592 31.1966 6.40434 32.1281 6.40434C32.7452 6.40434 33.2812 6.60581 33.7412 7.01008C34.2013 7.41567 34.4305 7.90719 34.4305 8.48649V8.8667C33.7907 8.50553 32.9731 8.32441 31.9822 8.32441C30.8228 8.32441 29.895 8.59569 29.1993 9.1393C28.505 9.6829 28.1576 10.4129 28.1576 11.3291C28.1576 12.2452 28.4871 12.9231 29.1459 13.5035C29.8035 14.0839 30.6247 14.3728 31.603 14.3728C32.751 14.3728 33.6698 13.866 34.3581 12.8523H34.4316V14.0841H36.0256V8.6134C36.0256 7.46644 35.6708 6.5643 34.9575 5.90674L34.9577 5.90647ZM33.6058 12.1096C33.0546 12.6278 32.4311 12.8877 31.7291 12.8877C31.2336 12.8877 30.8027 12.7433 30.4341 12.4544C30.0639 12.163 29.8804 11.8018 29.8804 11.3671C29.8804 10.883 30.1073 10.4801 30.561 10.1543C31.0134 9.82859 31.5787 9.66519 32.2553 9.66519C33.1854 9.66519 33.9115 9.86931 34.431 10.281C34.431 10.9806 34.1561 11.59 33.6061 12.1096H33.6058Z"
        fill={fill}
      />
      <path
        d="M26.9893 2.23873C26.2024 1.491 25.2493 1.11608 24.1253 1.11608H19.7013V14.0849H21.3689V8.83103H24.125C25.2604 8.83103 26.2159 8.46351 26.989 7.7261C27.7886 6.99106 28.1865 6.07227 28.1865 4.97369C28.1865 3.8751 27.7886 2.98804 26.989 2.23899L26.9893 2.23873ZM25.8119 6.56776C25.3759 7.0138 24.8259 7.23801 24.162 7.23801H21.3692V2.7091H24.162C24.8259 2.7091 25.3762 2.9386 25.8119 3.39733C26.2593 3.8447 26.4822 4.37059 26.4822 4.97369C26.4822 5.57678 26.259 6.12171 25.8119 6.56776Z"
        fill={fill}
      />
      <path
        d="M14.4307 10.116C14.0957 11.2637 13.476 12.3367 12.6093 13.1613C12.5813 13.188 12.553 13.2142 12.5247 13.2404C12.5231 13.242 12.522 13.2433 12.5205 13.2446C11.6683 14.0299 10.6004 14.5756 9.46927 14.8397C9.45896 14.8424 9.44838 14.8448 9.43807 14.8471C9.09197 14.9257 8.74032 14.983 8.38681 15.0187C7.82179 15.0753 7.25068 15.0753 6.68672 15.0127C6.40619 14.9817 6.12698 14.9352 5.85121 14.8723C5.76026 14.8516 5.66983 14.8294 5.57967 14.8051C4.58447 14.5391 3.64849 14.0672 2.84313 13.426C2.66307 13.2816 2.48936 13.1288 2.32279 12.9688C2.31776 12.9641 2.313 12.9593 2.30798 12.9548C1.72075 12.3898 1.225 11.7283 0.84849 11.0038C0.83289 10.9734 0.81729 10.9433 0.801955 10.9129C0.63644 10.5855 0.496044 10.246 0.381294 9.89835C0.323655 9.72491 0.272625 9.54881 0.228206 9.37114C0.201237 9.26458 0.176648 9.15777 0.154967 9.05016C0.125354 8.90685 0.100236 8.76249 0.0793485 8.61786C-0.0451842 7.76411 -0.0237677 6.88895 0.148093 6.0426C0.156289 6.00135 0.16475 5.96064 0.173739 5.91939C0.306733 5.30519 0.517196 4.71081 0.801691 4.14923C1.35825 3.03874 2.20037 2.0758 3.21593 1.36192H3.2162C3.31535 1.29185 3.41582 1.22496 3.51788 1.16018C3.54352 1.14405 3.56944 1.12819 3.59482 1.11206C3.64638 1.08033 3.69846 1.04913 3.75055 1.01846C3.85525 0.957648 3.96128 0.898951 4.06889 0.842898C4.12283 0.814872 4.1765 0.787639 4.23097 0.761198C4.50277 0.627941 4.78277 0.511869 5.06938 0.413512C5.11909 0.396061 5.16879 0.379669 5.2185 0.36354C5.29333 0.33948 5.36815 0.316477 5.44377 0.294796C5.49427 0.279989 5.5453 0.266241 5.59607 0.252756C5.6463 0.239272 5.69707 0.226581 5.74757 0.214154C5.77639 0.207015 5.80494 0.200405 5.83376 0.193531C5.87977 0.182955 5.92551 0.172907 5.97178 0.163124C5.97469 0.162596 5.97733 0.162067 5.97998 0.161274C6.12566 0.130603 6.27214 0.104428 6.41941 0.0827467C6.43422 0.0803671 6.44902 0.0782519 6.46409 0.0764011C7.69593 -0.0991609 8.97272 0.027487 10.1419 0.460046C11.0401 0.788961 11.8624 1.31194 12.5667 1.96105C12.3306 2.21408 12.0776 2.45442 11.8327 2.70322C11.369 3.16301 10.9095 3.62677 10.4454 4.0863C10.4449 4.08577 10.4438 4.08524 10.4433 4.08418L10.437 4.09053C9.97745 3.65189 9.42088 3.32298 8.81356 3.13737C8.101 2.92241 7.33371 2.89253 6.60422 3.04879C6.34088 3.10458 6.08388 3.18549 5.83614 3.2894C5.83323 3.29045 5.83059 3.29178 5.82768 3.29283C5.28064 3.52551 4.78039 3.86843 4.36502 4.2928C3.87138 4.79013 3.4962 5.40592 3.27278 6.06798C3.27119 6.06692 3.26961 6.0656 3.26802 6.06454C2.94386 7.00475 2.94809 8.05442 3.26828 8.99437C3.26643 8.99595 3.26458 8.99727 3.26273 8.99886C3.26326 8.99992 3.26352 9.00098 3.26379 9.00203C3.26537 9.00124 3.2667 8.99992 3.26828 8.99886C3.58028 9.92664 4.19183 10.7487 4.99323 11.3097C5.4948 11.6638 6.06828 11.9128 6.67138 12.0347C7.26179 12.1529 7.87731 12.1402 8.46772 12.0392C9.05813 11.9379 9.62738 11.7185 10.125 11.3856C10.125 11.3856 10.1252 11.3858 10.1255 11.3861C10.1282 11.3845 10.1308 11.383 10.1332 11.3811C10.9192 10.8494 11.471 9.9975 11.6302 9.06205H7.52725V6.12298H7.53148V6.11875H14.6201C14.8562 7.44286 14.8057 8.82171 14.4302 10.1162L14.4307 10.116Z"
        fill={fill}
      />
    </chakra.svg>
  );
};

/**
 * Fixed-size (48×24) centring box for a Pay-mark logo, passed as `ZimmButton`'s `iconLeading`.
 * Necessary despite `ZimmButton` already wrapping `iconLeading` in its own centred, `aria-hidden`
 * span: that outer span sizes itself to its *content*, so without this inner fixed box the Apple
 * mark's own 48×24 and Google's own 45×18 intrinsic sizes would produce two differently-sized
 * icon columns, misaligning the two buttons' text labels by the ~3px difference. This box is the
 * "shared fixed-size wrapper (48×24, matching ZimmButton's children slot for both)" plan.md step
 * 5.1 calls for — both marks render inside the same box regardless of their own real size.
 */
const PayMarkSlot = ({ children }: { children: React.ReactNode }) => (
  <chakra.span
    display="flex"
    alignItems="center"
    justifyContent="center"
    flexShrink={0}
    width={PAY_MARK_SLOT_WIDTH}
    height={PAY_MARK_SLOT_HEIGHT}
  >
    {children}
  </chakra.span>
);

/**
 * Molecule — the cart drawer's Checkout / Apple Pay / Google Pay button stack (SFCC-275, SFCC-11
 * plan step 5.1). No props: `checkoutOwner` is read directly from `useCountryConfig()` and the
 * Checkout navigation branch is resolved internally, rather than via an `onCheckoutClick`/`href`
 * prop the not-yet-built cart container (step 4.6) would otherwise need to supply — see this
 * file's own architecture note below for why, and the decision log at the bottom of this file for
 * every judgement call made while building it.
 *
 * Architecture note — navigation ownership. `components.md`'s container/presentational rule keeps
 * *data-fetching* out of `overrides/app/components/`, but reading site/locale config
 * (`useCountryConfig`, itself a thin read over `useMultiSite()`'s already-mounted context — no
 * fetch of its own) and triggering a route change (`useNavigation`, a `history.push` wrapper, not
 * a data source) are a different category from an SDK/React-Query data fetch — the same
 * distinction `ZimmCartItemActions` already draws for its own `useWishlistAuthDrawer` call
 * (`index.tsx`'s own architecture note: "an auth-gating hook rather than a data-fetching one").
 * `ZimmSearchInput` (`app/components/ui-kits/atoms/zimmSearchInput/index.tsx`) is the direct,
 * already-shipped precedent for calling `useNavigation()` from inside a `ui-kits/` leaf.
 *
 * This differs from `ZimmCartItemActions`' own shape, which takes `onRemove`/`onMoveToWishlist`
 * as caller-supplied callback props specifically because the *real mutation* is the not-yet-built
 * container's responsibility (step 4.6). There is no equivalent "real mutation" for the Checkout
 * button to defer: plan.md step 5.1 pass criterion 6 requires the domestic-vs-international
 * navigation branch to be provable from *this* component's own test file, before step 4.6 exists
 * — so the branch (and the `useCountryConfig`/`useNavigation` calls it needs) has to live here,
 * not behind a prop only a container built later could wire up. If a future step needs to
 * override the destination (e.g. once SFCC-880/SFCC-63 land for real), extending this component
 * with an optional override prop is a small, additive change — not a reason to invent one now for
 * a caller that doesn't exist yet (conventions.md's DRY/KISS guidance against speculative
 * abstraction).
 */
export const ZimmCartButtonGroup = () => {
  const intl = useIntl();
  const styles = useStyleConfig(ZIMM_CART_BUTTON_GROUP_RECIPE);
  const { checkoutOwner } = useCountryConfig();
  const navigate = useNavigation() as NavigateFn;

  // 'global-e' (HK, ME, and the not-yet-live en-ca/en-ch) is the only checkoutOwner value that
  // hides the express buttons — see this file's decision log, item 2, for why 'hybrid' (US)
  // groups with 'sfcc' as domestic here.
  const isInternational = checkoutOwner === 'global-e';

  const handleCheckoutClick = () => {
    if (isInternational) {
      navigateInternationalCheckoutStub(navigate);
      return;
    }
    navigate('/checkout');
  };

  return (
    <chakra.div __css={styles}>
      <ZimmButton
        variant="primary"
        label={intl.formatMessage(messages.checkout)}
        fullWidth
        onClick={handleCheckoutClick}
      />
      {!isInternational && (
        <>
          <ZimmButton
            variant="secondary"
            label={intl.formatMessage(messages.applePay)}
            fullWidth
            hideLabelVisually
            iconLeading={
              <PayMarkSlot>
                <ApplePayMark />
              </PayMarkSlot>
            }
          />
          <ZimmButton
            variant="secondary"
            label={intl.formatMessage(messages.googlePay)}
            fullWidth
            hideLabelVisually
            iconLeading={
              <PayMarkSlot>
                <GooglePayMark />
              </PayMarkSlot>
            }
          />
        </>
      )}
    </chakra.div>
  );
};

// --- Decision log -------------------------------------------------------------------------
// 1. <img src> rejected for both Pay marks, inline SVG used instead — this project's real
//    webpack config (node_modules/@salesforce/pwa-kit-dev/configs/webpack/config.js) applies
//    `ignore-loader` to every client-side `.svg` import with no path scoping (confirmed by
//    reading that file directly, not inferred) — an <img src> pointing at either committed asset
//    would render blank in the real app despite passing both Vitest (its own separate SVG
//    transform yields a raw path string, per testing.md's Known gap) and Storybook (whose
//    .storybook/main.js explicitly carves project-owned SVGs out to `asset/resource`, unlike the
//    real app). `ZimmLogo` already hit and documented this exact constraint. Flagged prominently
//    in this step's own report for Marcel — the plan's "(2) Apple Pay / Google Pay marks" section
//    and step 5.1's own text both specify `<img src>` without knowing about this constraint.
// 2. checkoutOwner: 'hybrid' (US) is treated as domestic (renders all three buttons), same as
//    'sfcc' — only 'global-e' hides the express buttons. This is my own inference from the
//    country data, not a literal quote from countries.ts's CheckoutOwner doc comment (that
//    comment describes what each owner means, it doesn't itself group 'hybrid' with 'sfcc' for
//    button-group purposes): 'hybrid' sites carry `globalEPricing: false`, the same as 'sfcc'
//    sites, while every actual 'global-e' site carries `globalEPricing: true` — and every
//    storefront named as the international button-group case (session-notes.md's Figma reference
//    list; the plan's own AC text) is 'global-e' (HK, ME), none is 'hybrid'. Not something
//    plan.md's step 5.1 text resolves explicitly for the three-way type; flagged in this step's
//    report rather than silently assumed only in this comment.
// 3. Apple Pay / Google Pay render icon-only, matching Figma exactly — CORRECTED after this
//    step's coordinator independently confirmed the mismatch against a live Figma screenshot of
//    the real button-group frame (node 9323:95939), not just Figma's prose. The original build
//    of this component shipped a visible "Apple Pay"/"Google Pay" text label next to the logo,
//    disclosed as a gap rather than silently shipped — but a live-photograph-confirmed mismatch
//    against the actual design is a defect to fix, not a defensible interpretation gap, so it
//    isn't one anymore: `ZimmButton` (`ui-kits/atoms/zimmButton/index.tsx`) now takes a
//    `hideLabelVisually` prop, applied to both buttons here, which swaps the visible label span
//    for Chakra's `VisuallyHidden` — the label text stays a real DOM node (so nothing about the
//    accessible name changes; `aria-label` on `ZimmButton` was already unconditional) but is no
//    longer shown on screen. Live-reverified in Storybook after the fix (see this step's report).
// 4. useExpressCheckoutEnabled() checked (per plan.md step 5.1's own instruction) but not wired
//    into this component: it gates a *different* axis (device/browser eligibility, SFCC-309, not
//    yet scoped — session-notes.md's "SFCC-309 overlap, resolved" note) from the region-based
//    hide this component owns. Wiring it in would be scope this step wasn't asked to add.
// 5. No props. checkoutOwner/navigation are resolved internally — see the architecture note above
//    the component for why, and for the deliberate difference from ZimmCartItemActions' own
//    callback-prop shape.

