1	import React from 'react';
2	import { describe, test, expect, vi, beforeEach } from 'vitest';
3	import { render, screen, fireEvent } from '@testing-library/react';
4	import { ChakraProvider } from '@chakra-ui/react';
5	import { IntlProvider } from 'react-intl';
6	import theme from 'app/theme';
7	import { ZimmCartButtonGroup, navigateInternationalCheckoutStub, messages } from './index';
8	import { ZimmCartButtonGroup as ZimmCartButtonGroupRecipe } from './zimmCartButtonGroup.css';
9	import { Button } from 'app/components/ui-kits/atoms/zimmButton/zimmButton.css';
10	import { actionSizes } from 'app/theme/foundation/sizes';
11	import { zimmTokens } from 'app/theme/foundation/zimmTokens';
12	
13	// `mockNavigate`/`mockUseCountryConfig` are referenced from inside the `vi.mock(...)` factories
14	// below, which Vitest hoists above this file's own top-level `const`s — `vi.hoisted` avoids the
15	// resulting TDZ error. Same pattern as zimmCartItemActions/index.test.tsx's own hoisted mocks.
16	const { mockNavigate, mockUseCountryConfig } = vi.hoisted(() => ({
17	  mockNavigate: vi.fn(),
