112	/** Atom — labelled button (primary/secondary/social) or icon-only button. All visual states
113	 *  are handled by `zimmButton.css.ts` (co-located beside this file) — no React state for hover/press/focus.
114	 *  Labelled variants accept optional `iconLeading` and `iconTrailing` nodes rendered either
115	 *  side of the label; gap between icon and text is set by the button's flex gap in baseStyle. */
116	export const ZimmButton = (props: ZimmButtonProps) => {
